// CHECK-IR-LABEL: define dso_local <vscale x 16 x float> @__riscv_vle32_v_f32m8_f32m1
// CHECK-IR-SAME: (ptr noundef [[PTR:%.*]]) #[[ATTR0:[0-9]+]] {
// CHECK-IR-NEXT:  entry:
// CHECK-IR-NEXT:    [[TMP0:%.*]] = call i64 @llvm.riscv.th.vsetvl.i64(i64 32, i64 2, i64 3)
// CHECK-IR-NEXT:    [[TMP1:%.*]] = call <vscale x 16 x i32> @llvm.riscv.th.vle.nxv16i32.i64(<vscale x 16 x i32> poison, ptr @__riscv_vle32_v_f32m8_f32m1.index_128bit, i64 [[TMP0]])
// CHECK-IR-NEXT:    [[TMP2:%.*]] = call <vscale x 16 x float> @llvm.riscv.th.vlxe.nxv16f32.nxv16i32.i64(<vscale x 16 x float> poison, ptr [[PTR]], <vscale x 16 x i32> [[TMP1]], i64 [[TMP0]])
// CHECK-IR-NEXT:    ret <vscale x 16 x float> [[TMP2]]
//
vfloat32m8_t __riscv_vle32_v_f32m8_f32m1(const float* ptr)
{
    const int packn = 4;
    const size_t vl = __riscv_vsetvl_e32m8(packn * 8);

    // NOTE vloxei8_v_f32m8 gets illegal instruction on d1  --- nihui

    // 128bit
    static const uint32_t index_128bit[32] = {
        0, 4, 8, 12,
        0, 4, 8, 12,
        0, 4, 8, 12,
        0, 4, 8, 12,
        0, 4, 8, 12,
        0, 4, 8, 12,
        0, 4, 8, 12,
        0, 4, 8, 12
    };

    vuint32m8_t bindex = __riscv_vle32_v_u32m8(index_128bit, vl);
    return __riscv_vloxei32_v_f32m8(ptr, bindex, vl);
}
